const crypto = require('crypto');
const secret = $env.LENDLOOP_SHARED_SECRET;
if (!secret) throw new Error('LENDLOOP_SHARED_SECRET is not set');
const sign = (ts, body) => crypto.createHmac('sha256', secret).update(`${ts}.${body}`).digest('hex');

// Verify the HMAC signature from Convex before trusting anything in the payload.
const item = $input.first();
const headers = item.json.headers ?? {};
const ts = headers['x-lendloop-timestamp'];
const sig = headers['x-lendloop-signature'];
let raw;
if (item.binary?.data) {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} else {
  raw = JSON.stringify(item.json.body);
}
const fresh = ts && Math.abs(Date.now() - Number(ts)) < 5 * 60 * 1000;
const expected = ts ? sign(ts, raw) : '';
const valid = Boolean(
  fresh && sig && sig.length === expected.length &&
  crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected))
);
if (!valid) return [{ json: { valid: false } }];

const body = JSON.parse(raw);
// Drop duplicates: Convex retries with the same eventKey.
const store = $getWorkflowStaticData('global');
store.seen = store.seen ?? [];
const duplicate = store.seen.includes(body.eventKey);
if (!duplicate) {
  store.seen.push(body.eventKey);
  store.seen = store.seen.slice(-500);
}
// Keep only the fields the notification needs.
return [{ json: {
  valid: true,
  duplicate,
  eventKey: body.eventKey,
  event: body.event,
  to: body.recipient,
  toolName: body.toolName,
  otherPartyName: body.otherPartyName,
  startDate: body.startDate,
  endDate: body.endDate,
} }];

// Mock notification: logs what would be emailed. Swap for an Email/Slack node in production.
const j = $input.first().json;
const lines = {
  'loan.pending': `${j.otherPartyName} wants to borrow your ${j.toolName} (${j.startDate} → ${j.endDate}).`,
  'loan.approved': `${j.otherPartyName} approved your request for the ${j.toolName} (${j.startDate} → ${j.endDate}).`,
  'loan.declined': `${j.otherPartyName} declined your request for the ${j.toolName}.`,
  'loan.cancelled': `${j.otherPartyName} cancelled the request for your ${j.toolName}.`,
  'loan.returned': `${j.otherPartyName} marked the ${j.toolName} as returned. Thanks for borrowing!`,
};
const text = lines[j.event];
if (!text) throw new Error(`Unknown event ${j.event}`);
const message = { to: j.to.email, name: j.to.name, subject: 'LendLoop update', text };
console.log('[LendLoop notification]', JSON.stringify(message));
return [{ json: { ok: true, eventKey: j.eventKey, channel: 'mock-log', message } }];
